(function (global) {
  'use strict';
  global.Art = {
    bust: {"police": {"m": "data:image/jpeg;base64,", "f": "data:image/jpeg;base64,"}, "fire": {"m": "data:image/jpeg;base64,", "f": "data:image/jpeg;base64,"}, "army": {"m": "data:image/jpeg;base64,", "f": "data:image/jpeg;base64,"}, "doctor": {"m": "data:image/jpeg;base64,", "f": "data:image/jpeg;base64,"}},
    sel: {"police": "data:image/jpeg;base64,", "fire": "data:image/jpeg;base64,", "army": "data:image/jpeg;base64,", "doctor": "data:image/jpeg;base64,"},
    has: function (job, g) { return !!(global.Art.bust[job] && global.Art.bust[job][g]); }
  };
})(window);
